def test_output_length_matches_n(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    n = int(x.strip().split('\n')[0].split()[0])
    assert len(lines) == n, f'Expected {n} lines, got {len(lines)}'

def test_output_values_in_range(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    m = int(x.strip().split('\n')[0].split()[1])
    for line in lines:
        v = int(line.strip())
        assert 0 <= v <= m, f'Value {v} outside [0, {m}]'

def test_locked_core_has_nonzero_instruction(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instrs = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = run(x)
    deadstep = list(map(int, out.strip().split('\n')))
    for i in range(n):
        if deadstep[i] != 0:
            step = deadstep[i] - 1  # zero-indexed
            assert instrs[i][step] != 0, f'Core {i+1} locked on step {deadstep[i]} but instruction is 0'

def test_swap_cores_order_invariant(run, x):
    lines = x.strip().split('\n')
    parts = lines[0].split()
    n, m, k = int(parts[0]), int(parts[1]), int(parts[2])
    if n < 2:
        return
    # Swap first two cores
    swapped = lines[:1] + [lines[2], lines[1]] + lines[3:]
    swapped_input = '\n'.join(swapped)
    out1 = run(x).strip().split('\n')
    out2 = run(swapped_input).strip().split('\n')
    # Outputs should swap correspondingly
    assert out1[0] == out2[1] and out1[1] == out2[0], f'Swapping cores did not swap outputs'

def test_zero_instructions_after_lock_preserved(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    # Build a modified input where all instructions for a core after its lock step are set to 0
    instrs = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = run(x)
    deadstep = list(map(int, out.strip().split('\n')))
    new_instrs = [instrs[i][:] for i in range(n)]
    for i in range(n):
        if deadstep[i] != 0:
            lock_step_idx = deadstep[i] - 1
            for j in range(lock_step_idx + 1, m):
                new_instrs[i][j] = 0
    new_lines = [lines[0]] + [' '.join(map(str, row)) for row in new_instrs]
    new_input = '\n'.join(new_lines)
    out_orig = out.strip().split('\n')
    out_new = run(new_input).strip().split('\n')
    assert out_orig == out_new, f'Zeroing instructions after lock changed output'

def test_deadlock_consistency(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instrs = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = run(x)
    deadstep = list(map(int, out.strip().split('\n')))
    # Simulate deadlock tracking
    badmem = [False] * (k + 1)
    for step in range(1, m+1):
        writes = [0] * (k + 1)
        for i in range(n):
            if deadstep[i] == 0 or deadstep[i] > step:
                cell = instrs[i][step-1]
                if cell != 0:
                    writes[cell] += 1
        for cell in range(1, k+1):
            if writes[cell] > 1:
                badmem[cell] = True
        for i in range(n):
            if deadstep[i] == 0:
                cell = instrs[i][step-1]
                if cell != 0 and badmem[cell]:
                    assert deadstep[i] == step, f'Core {i+1} should lock at step {step} but got {deadstep[i]}'

def test_deadlocked_cells_remain_deadlocked(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instrs = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = run(x)
    deadstep = list(map(int, out.strip().split('\n')))
    badmem = [False] * (k + 1)
    for step in range(1, m+1):
        writes = [0] * (k + 1)
        for i in range(n):
            if deadstep[i] == 0 or deadstep[i] > step:
                cell = instrs[i][step-1]
                if cell != 0:
                    writes[cell] += 1
        for cell in range(1, k+1):
            if writes[cell] > 1:
                badmem[cell] = True
        # Once a cell is deadlocked, any core writing to it this step must lock
        for i in range(n):
            if deadstep[i] == 0:
                cell = instrs[i][step-1]
                if cell != 0 and badmem[cell]:
                    assert deadstep[i] == step, f'Core {i+1} writing to deadlocked cell {cell} at step {step} did not lock'

def test_no_lock_before_first_write(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instrs = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = run(x)
    deadstep = list(map(int, out.strip().split('\n')))
    for i in range(n):
        first_write = next((j+1 for j, val in enumerate(instrs[i]) if val != 0), m+1)
        if deadstep[i] != 0:
            assert deadstep[i] >= first_write, f'Core {i+1} locked at {deadstep[i]} before first write at {first_write}'

def test_if_cell_deadlocked_all_writers_lock(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instrs = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = run(x)
    deadstep = list(map(int, out.strip().split('\n')))
    # For each step, compute writers to each cell among not‑yet‑locked cores
    for step in range(1, m+1):
        writers_per_cell = {cell: [] for cell in range(1, k+1)}
        for i in range(n):
            if deadstep[i] == 0 or deadstep[i] > step:
                cell = instrs[i][step-1]
                if cell != 0:
                    writers_per_cell[cell].append(i)
        for cell, writers in writers_per_cell.items():
            if len(writers) > 1:
                # All these writers must lock at this step
                for i in writers:
                    assert deadstep[i] == step, f'Core {i+1} writing to cell {cell} with multiple writers at step {step} did not lock'

def test_no_lock_if_no_write_or_single_writer(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instrs = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = run(x)
    deadstep = list(map(int, out.strip().split('\n')))
    for step in range(1, m+1):
        writers_per_cell = {cell: [] for cell in range(1, k+1)}
        for i in range(n):
            if deadstep[i] == 0 or deadstep[i] > step:
                cell = instrs[i][step-1]
                if cell != 0:
                    writers_per_cell[cell].append(i)
        for cell, writers in writers_per_cell.items():
            if len(writers) <= 1:
                # None of these writers should lock solely due to this cell this step
                # (They could lock due to another deadlocked cell)
                pass  # This is harder to assert without full simulation; we rely on other tests

