tests_src:
def test_output_format(run, x):
    output = run(x)
    # Output must be exactly 'Heisei\n' or 'TBD\n' (with newline)
    assert output in ['Heisei\n', 'TBD\n'], f'Invalid output format: {repr(output)}'

def test_heisei_implies_before_or_on_2019_04_30(run, x):
    output = run(x)
    if output == 'Heisei\n':
        # Parse date
        parts = x.strip().split('/')
        year, month, day = int(parts[0]), int(parts[1]), int(parts[2])
        # Must satisfy (year == 2019) and (month < 4 or (month == 4 and day <= 30))
        assert year == 2019
        assert month < 4 or (month == 4 and day <= 30)

def test_tbd_implies_after_2019_04_30(run, x):
    output = run(x)
    if output == 'TBD\n':
        parts = x.strip().split('/')
        year, month, day = int(parts[0]), int(parts[1]), int(parts[2])
        assert year == 2019
        assert month > 4 or (month == 4 and day > 30)

def test_idempotence(run, x):
    # Running same input twice should give same output
    output1 = run(x)
    output2 = run(x)
    assert output1 == output2

def test_2019_04_30_is_heisei(run, x):
    if x == '2019/04/30\n':
        assert run(x) == 'Heisei\n'

def test_2019_05_01_is_tbd(run, x):
    if x == '2019/05/01\n':
        assert run(x) == 'TBD\n'

def test_2019_04_29_is_heisei(run, x):
    if x == '2019/04/29\n':
        assert run(x) == 'Heisei\n'

def test_month_before_april_is_heisei(run, x):
    parts = x.strip().split('/')
    month = int(parts[1])
    if month < 4:
        assert run(x) == 'Heisei\n'

def test_month_after_april_is_tbd(run, x):
    parts = x.strip().split('/')
    month = int(parts[1])
    if month > 4:
        assert run(x) == 'TBD\n'

def test_output_not_empty(run, x):
    output = run(x)
    assert len(output) > 0

