def test_n1_output_exact(run, x):
    if x.strip() == '1':
        out = run(x)
        assert out == 'Hello World\n', f'For N=1 expected "Hello World\\n", got {repr(out)}'

def test_n2_output_single_line(run, x):
    lines = x.strip().split('\n')
    if lines[0] == '2':
        out = run(x)
        lines_out = out.strip().split('\n')
        assert len(lines_out) == 1, f'For N=2 output should be one line, got {len(lines_out)} lines'

def test_n2_output_numeric(run, x):
    lines = x.strip().split('\n')
    if lines[0] == '2':
        out = run(x)
        assert out.strip().isdigit(), f'For N=2 output should be an integer, got {repr(out.strip())}'

def test_n2_output_non_negative(run, x):
    lines = x.strip().split('\n')
    if lines[0] == '2':
        out = run(x)
        val = int(out.strip())
        assert val >= 0, f'Sum should be non-negative, got {val}'

def test_n2_output_bound(run, x):
    lines = x.strip().split('\n')
    if lines[0] == '2':
        a = int(lines[1])
        b = int(lines[2])
        out = run(x)
        val = int(out.strip())
        assert 2 <= val <= 18, f'Sum should be between 2 and 18, got {val}'

def test_metamorphic_swap(run, x):
    lines = x.strip().split('\n')
    if lines[0] == '2':
        a = lines[1]
        b = lines[2]
        swapped_input = '\n'.join(['2', b, a]) + '\n'
        out1 = run(x)
        out2 = run(swapped_input)
        assert out1 == out2, f'Swapping A and B should give same sum, got {out1.strip()} vs {out2.strip()}'

def test_certificate_sum(run, x):
    lines = x.strip().split('\n')
    if lines[0] == '2':
        a = int(lines[1])
        b = int(lines[2])
        out = run(x)
        val = int(out.strip())
        assert val == a + b, f'Sum should be {a}+{b}={a+b}, got {val}'

def test_n1_no_digits(run, x):
    if x.strip() == '1':
        out = run(x)
        assert not any(c.isdigit() for c in out), f'For N=1 output should contain no digits, got {out}'

def test_output_ends_with_newline(run, x):
    out = run(x)
    assert out.endswith('\n'), f'Output must end with newline, got {repr(out)}'

def test_output_length_reasonable(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    if lines[0] == '1':
        assert len(out.strip()) == len('Hello World'), f'For N=1 output length mismatch, got {repr(out)}'
    else:
        val = out.strip()
        assert 1 <= len(val) <= 2, f'For N=2 output length should be 1-2 digits, got {len(val)} digits'

