        b = int(lines[2])
        out = run(x).strip()
        val = int(out)
        # Sum must be between 2 and 18
        assert 2 <= val <= 18, f"Sum {val} out of range [2,18] for A={a}, B={b}"

def test_n2_sum_consistency(run, x):
    if x.strip().startswith('2'):
        lines = x.strip().split('\n')
        a = int(lines[1])
        b = int(lines[2])
        out = run(x).strip()
        val = int(out)
        # The specification says print A+B
        assert val == a + b, f"Output {val} does not equal A+B={a+b}"

def test_n2_metamorphic_swap(run, x):
    if x.strip().startswith('2'):
        lines = x.strip().split('\n')
        a = int(lines[1])
        b = int(lines[2])
        # Build swapped input
        swapped = f"2\n{b}\n{a}"
        out1 = run(x).strip()
        out2 = run(swapped).strip()
        # Sum is commutative, so outputs must be equal
        assert out1 == out2, f"Swapping A and B changed output: {out1} vs {out2}"

def test_n2_output_no_extra(run, x):
    if x.strip().startswith('2'):
        out = run(x)
        # Should be a single integer possibly with newline
        lines = out.strip().split('\n')
        assert len(lines) == 1, f"Output has extra lines: {repr(out)}"
        # No leading/trailing spaces except newline
        assert out.strip() == out.rstrip('\n'), f"Extra whitespace in output: {repr(out)}"

def test_n1_output_no_number(run, x):
    if x.strip().startswith('1'):
        out = run(x)
        # Must not be a numeric string
        stripped = out.strip()
        try:
            int(stripped)
            assert False, f"When N=1 output should not be a number, got {repr(out)}"
        except ValueError:
            pass

def test_n2_output_positive(run, x):
    if x.strip().startswith('2'):
        out = run(x).strip()
        val = int(out)
        # A,B >=1 so sum >=2
        assert val >= 2, f"Output {val} is less than 2"

def test_n2_output_parsable(run, x):
    if x.strip().startswith('2'):
        out = run(x)
        # Must be able to parse as int without crashing
        try:
            int(out.strip())
        except Exception as e:
            assert False, f"Output {repr(out)} not a valid integer: {e}"

def test_n2_output_matches_input(run, x):
