def test_output_is_yes_or_no(run, x):
    out = run(x).strip()
    assert out in {"YES", "NO"}, f"Output must be YES or NO, got {out}"

def test_all_same_letters_is_no(run, x):
    lines = x.strip().split('\n')[1:]
    n = len(lines)
    first = lines[0][0]
    if all(c == first for row in lines for c in row):
        out = run(x).strip()
        assert out == "NO", f"All letters same must be NO, got {out}"

def test_if_yes_exactly_two_letters(run, x):
    out = run(x).strip()
    if out == "YES":
        lines = x.strip().split('\n')[1:]
        letters = {c for row in lines for c in row}
        assert len(letters) == 2, f"When YES, exactly two letters must appear, got {letters}"

def test_mirror_horizontal_preserves_answer(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    grid = lines[1:]
    mirrored = [row[::-1] for row in grid]
    new_input = f"{n}\n" + '\n'.join(mirrored)
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    assert out1 == out2, f"Mirroring should not change answer: {out1} vs {out2}"

def test_transpose_preserves_answer(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    grid = lines[1:]
    transposed = [''.join(grid[j][i] for j in range(n)) for i in range(n)]
    new_input = f"{n}\n" + '\n'.join(transposed)
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    assert out1 == out2, f"Transpose should not change answer: {out1} vs {out2}"

def test_swap_letters_inverts_if_two_letters(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    grid = lines[1:]
    letters = {c for row in grid for c in row}
    if len(letters) == 2:
        a, b = letters
        swapped_grid = [''.join(b if c == a else a for c in row) for row in grid]
